struct key *construct_and_link_key(struct keyring_search_context *ctx,
                                   const char *callout_info,
                                   size_t callout_len,
                                   void *aux,
                                   struct key *dest_keyring,
                                   unsigned long flags) {
    struct key *key;
    int ret;

    if (!ctx || !dest_keyring) {
        return ERR_PTR(-EINVAL);
    }

    key = key_alloc(&key_type_user, NULL, current_cred(), NULL, flags, NULL, NULL);
    if (IS_ERR(key)) {
        return key;
    }

    key->description = kstrdup("dynamic_key", GFP_KERNEL);
    if (!key->description) {
        ret = -ENOMEM;
        goto error_free_key;
    }

    if (callout_info && callout_len > 0) {
        key->callout_info = kmemdup(callout_info, callout_len, GFP_KERNEL);
        if (!key->callout_info) {
            ret = -ENOMEM;
            goto error_free_desc;
        }
        key->callout_len = callout_len;
    }

    ret = key_instantiate(key, aux, 0);
    if (ret < 0) {
        goto error_free_callout;
    }

    ret = key_link(dest_keyring, key);
    if (ret < 0) {
        goto error_free_callout;
    }

    return key;

error_free_callout:
    if (key->callout_info) {
        kfree(key->callout_info);
    }
error_free_desc:
    kfree(key->description);
error_free_key:
    key_put(key);
    return ERR_PTR(ret);
}

